#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"

failures=0

pass() {
  printf 'PASS %s\n' "$1"
}

fail() {
  printf 'FAIL %s\n' "$1" >&2
  failures=$((failures + 1))
}

require_file() {
  local path="$1"
  local label="$2"

  if [[ -f "$path" ]]; then
    pass "$label"
  else
    fail "$label: missing $path"
  fi
}

require_pattern() {
  local pattern="$1"
  local path="$2"
  local label="$3"

  if rg -n -U --pcre2 --hidden --glob '!.git/**' "$pattern" "$path" >/dev/null; then
    pass "$label"
  else
    fail "$label"
  fi
}

require_absent_pattern() {
  local pattern="$1"
  local path="$2"
  local label="$3"

  if rg -n -U --pcre2 --hidden --glob '!.git/**' "$pattern" "$path" >/tmp/slsknet-runtime-remediation-hit.$$ 2>/dev/null; then
    fail "$label"
    sed 's/^/  /' /tmp/slsknet-runtime-remediation-hit.$$ >&2
  else
    pass "$label"
  fi

  rm -f /tmp/slsknet-runtime-remediation-hit.$$
}

